 3	final class BinarySearch {
 4	    private static final int NOT_FOUND = -1;
 5	    private static final int[] SAMPLE_VALUES = { 2, 3, 4, 10, 40 };
 6	    private static final int SAMPLE_TARGET = 10;
 7	
 8	    private BinarySearch() {
 9	    }
10	
11	    static int binarySearch(int[] arr, int target) {
12	        return findIndex(arr, target).orElse(NOT_FOUND);
13	    }
14	
15	    static OptionalInt findIndex(int[] arr, int target) {
16	        int low = 0;
17	        int high = arr.length - 1;
18	
19	        while (low <= high) {
20	            int middleIndex = low + (high - low) / 2;
21	            int middleValue = arr[middleIndex];
22	
23	            if (middleValue == target) {
24	                return OptionalInt.of(middleIndex);
25	            }
26	
27	            if (middleValue < target) {
28	                low = middleIndex + 1;
29	            } else {
30	                high = middleIndex - 1;
31	            }
32	        }
33	
34	        return OptionalInt.empty();
35	    }
36	
37	    private static String formatSearchResult(OptionalInt result) {
38	        return result.isEmpty()
39	                ? "Element is not present in array"
40	                : "Element is present at index " + result.getAsInt();
41	    }
42	
43	    public static void main(String[] args) {
44	        OptionalInt result = findIndex(SAMPLE_VALUES, SAMPLE_TARGET);
45	
46	        System.out.println(formatSearchResult(result));
47	    }
48	}
